INSERT INTO noticias (titulo, slug, extracto, contenido, categoria_id, autor_id, estado, destacada, destacada_orden, imagen_destacada_url, imagen_alt, meta_titulo, meta_descripcion, fecha_publicacion, origen) VALUES
  ('Cobreloa suma puntos clave en Sub-20 Nacional', 'cobreloa-suma-puntos-clave-en-sub-20-nacional', 'Cobreloa suma puntos clave en Sub-20 Nacional. Cobertura ChilenosProyección con foco en fútbol joven chileno.', '<p>Cobreloa suma puntos clave en Sub-20 Nacional. Cobertura ChilenosProyección con foco en fútbol joven chileno.</p><h2>Lo que pasó en la cancha</h2><p>El trabajo de cantera de <strong>Cobreloa</strong> sigue dando frutos. <strong>Catalina Soto</strong> fue figura con números que llaman la atención en formativas.</p><h2>Proyección</h2><p>Desde la redacción seguimos de cerca el desarrollo de las categorías Sub-20 a Infantil, con tablas, goleadores y crónicas de fin de semana.</p>', 11, 1, 'publicado', 1, 1, '/assets/brand/goleadores-regional.jpg', 'Cobreloa suma puntos clave en Sub-20 Nacional', 'Cobreloa suma puntos clave en Sub-20 Nacional | ChilenosProyección', 'Cobreloa suma puntos clave en Sub-20 Nacional. Cobertura ChilenosProyección con foco en fútbol joven chileno.', NOW() - INTERVAL 5 HOUR, 'manual'),
  ('Debut prometedor: Álvaro Morales en Colchagua', 'debut-prometedor-alvaro-morales-en-colchagua', 'Debut prometedor: Álvaro Morales en Colchagua. Cobertura ChilenosProyección con foco en fútbol joven chileno.', '<p>Debut prometedor: Álvaro Morales en Colchagua. Cobertura ChilenosProyección con foco en fútbol joven chileno.</p><h2>Lo que pasó en la cancha</h2><p>El trabajo de cantera de <strong>Colchagua</strong> sigue dando frutos. <strong>Álvaro Morales</strong> fue figura con números que llaman la atención en formativas.</p><h2>Proyección</h2><p>Desde la redacción seguimos de cerca el desarrollo de las categorías Sub-20 a Infantil, con tablas, goleadores y crónicas de fin de semana.</p>', 12, 1, 'publicado', 1, 2, '/assets/brand/goleadores-sub14.jpg', 'Debut prometedor: Álvaro Morales en Colchagua', 'Debut prometedor: Álvaro Morales en Colchagua | ChilenosProyección', 'Debut prometedor: Álvaro Morales en Colchagua. Cobertura ChilenosProyección con foco en fútbol joven chileno.', NOW() - INTERVAL 10 HOUR, 'manual'),
